      this.winnerTouchStartX = e.touches[0].clientX
      this.winnerOffsetX += dx
    },
    onWinnerTouchEnd() {
      this.winnerClampOffset()
      this.winnerStartAutoplay()
    },
    winnerStartAutoplay() {
